import random
def parse(stdin):
    toks = stdin.split()
    if len(toks) != 2: raise ValueError()
    return [int(toks[0]), int(toks[1])]
def render(case):
    return f"{case[0]} {case[1]}"
def valid(case):
    return (isinstance(case, list) and len(case) == 2 and
            all(isinstance(x, int) and not isinstance(x, bool) and -100 <= x <= 100 for x in case))
def solve(stdin):
    a, b = parse(stdin)
    return str(a + b)
def generate(seed, index, mode):
    if mode == 'exhaustive':
        if index >= 121: return None
        return [index // 11 - 5, index % 11 - 5]
    if mode == 'random':
        rng = random.Random(seed + index)
        return [rng.randint(-100, 100), rng.randint(-100, 100)]
    b = [-100, 0, 100]
    return [[x, y] for x in b for y in b][index % 9]
def shrink(case):
    a, b = case
    cand = [[0, b], [a, 0], [int(a / 2), b], [a, int(b / 2)], [int(a / 2), int(b / 2)]]
    out = []
    for c in cand:
        if c != case and valid(c) and c not in out:
            out.append(c)
    return out[:16]

